package krbseal

import (
	"bytes"
	"crypto/hmac"
	"crypto/md5"
	"crypto/rc4"
	"encoding/binary"
	"encoding/hex"
	"testing"

	"github.com/go-krb5/krb5/types"
)

// Cross-implementation test vectors, generated by scripts/krbseal-vectors.py
// from impacket's impacket.krb5.gssapi -- an independent implementation of the
// same RFCs.
//
// These are the point of this file. Every test in seal_test.go builds its input
// with the production `wrap` and then asserts `unwrap` reads it back, so it can
// only catch layout and slicing mistakes: a self-consistent implementation of
// the *wrong* algorithm round-trips against itself perfectly and passes all of
// them. That matters most on the RC4 path, where this package hand-rolls RFC
// 4757 §7.3's HMAC-MD5 chains rather than delegating to a cryptosystem -- swap
// the HMAC nesting order, drop the xorF0, or change le32(0) to le32(1), and
// wrap/unwrap still agree with each other while agreeing with nobody else.
// Until these vectors landed, the only thing pinning that algorithm was the
// live matrix against a real Windows DC (docs/verification.md), which needs an
// ephemeral box and so cannot run in CI.
//
// Same role internal/auth/ntlmseal's vectors_test.go plays there, with one
// difference worth naming: ntlmseal's numbers are MS-NLMP's *published* values,
// while these are a second implementation's output. That is weaker ground truth
// -- impacket could in principle be wrong the same way -- but it is independent
// of this code, which is the property the round-trip tests lack. The RFCs
// publish no wrap-token vectors of their own; live agreement with Windows is
// what says impacket and krbseal are both right, and these vectors are what
// keeps a future edit from silently drifting off that agreement.
//
// The AES vector's independence is only partial: impacket's AES GSS_Wrap
// hardcodes Flags=6 and INITIATOR_SEAL, so it cannot express an acceptor-sealed
// token and the generator builds the RFC 4121 header itself. What that vector
// pins is the key usage, rotation direction, RRC and header layout against an
// independent *cryptosystem*. The AES payload crypto is go-krb5's, not ours,
// and is vector-tested upstream -- which is why the RC4 vector is the
// load-bearing one here.
const (
	vecRC4Key = "2b7e151628aed2a6abf7158809cf4f3c"
	vecAESKey = "606162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f"

	// 32 bytes: "<s:Envelope>whoami!</s:Envelope>". The length is a multiple of
	// 8 on purpose -- impacket applies RFC 1964 padding and krbseal
	// deliberately does not (WinRM's in-place SECBUFFER_DATA encryption adds
	// none), so only at a multiple of 8 do the two agree byte-for-byte.
	vecPlaintext = "3c733a456e76656c6f70653e77686f616d69213c2f733a456e76656c6f70653e"

	vecSeq = 7

	// impacket GSSAPI_RC4.GSS_Wrap(direction='accept') -- the direction krbseal
	// must read, and the one its direction tag demands.
	vecRC4Sig  = "602b06092a864886f712010202020111001000ffffe0bd1e0c047e8033464367286b789d0416dff1192f4ef360"
	vecRC4Data = "254a3c4541a47fac18cd4dea276c153d841e377b06d1e60a49c86406ca0cdb4d"

	// The two RC4 derived keys, which depend only on the session key and the
	// sequence number -- never on the confounder. That is what makes them
	// usable to check the *send* direction, whose output cannot be frozen
	// because wrapRC4 draws its confounder from crypto/rand.
	vecRC4Ksign  = "92695194bc3dd2efea092343540f3e19" // HMAC-MD5(key, "signaturekey\0")
	vecRC4Kcrypt = "d1fd56385ed03deea512e9e128c5eee7" // HMAC-MD5(HMAC-MD5(key^F0, le32(0)), be32(seq))

	// Acceptor-sealed AES256 wrap token: header per RFC 4121 §4.2.4, payload
	// through impacket's _AES256CTS at KG_USAGE_ACCEPTOR_SEAL (22).
	vecAESSig  = "050403ff0000001c0000000000000007f55d4364039802214ec346cb89819b03c33ae458b85591d72682c67a295e31ff04eeaf61c9813c31991c30d3"
	vecAESData = "d23681fb8bff74699c9d9193bc15c7138a1db33c980453af74f84ea0a83fa77c"
)

func vec(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad test vector %q: %v", s, err)
	}
	return b
}

// TestRC4UnwrapAcceptorVector is the highest-value test in this package: one
// call that proves krbseal's RFC 4757 unwrap agrees, byte for byte, with an
// implementation it shares no code with.
//
// It covers the whole receive chain at once -- Kseq (which decrypts SND_SEQ),
// the direction tag, Kcrypt (which decrypts the confounder and payload), and
// the SGN_CKSUM formula and its comparison. Any of those derived differently
// from impacket's yields either a failed check or garbage plaintext, and no
// amount of round-tripping against ourselves would notice, because both ends
// would be wrong together.
func TestRC4UnwrapAcceptorVector(t *testing.T) {
	key := vec(t, vecRC4Key)
	plain := vec(t, vecPlaintext)

	s, err := newSealer(types.EncryptionKey{KeyType: 23, KeyValue: key})
	if err != nil {
		t.Fatal(err)
	}
	got, err := s.unwrap(vec(t, vecRC4Sig), vec(t, vecRC4Data), len(plain))
	if err != nil {
		t.Fatalf("unwrap of impacket's token failed: %v", err)
	}
	if !bytes.Equal(got, plain) {
		t.Fatalf("plaintext mismatch:\n got %q\nwant %q", got, plain)
	}
}

// TestRC4UnwrapVectorRejectsTamper re-runs the integrity check against a
// *foreign* token rather than one this package sealed for itself. seal_test.go
// already tampers with self-produced tokens; the point here is that the check
// still bites on bytes whose SGN_CKSUM was computed elsewhere -- i.e. that
// passing the vector is not an artefact of our own wrap having produced it.
func TestRC4UnwrapVectorRejectsTamper(t *testing.T) {
	key := vec(t, vecRC4Key)
	plainLen := len(vec(t, vecPlaintext))

	for _, tc := range []struct {
		name string
		what string // "sig" or "data"
		at   int
	}{
		{"payload byte", "data", 3},
		{"checksum byte", "sig", 13 + 16}, // SGN_CKSUM starts 16 into the token
		{"direction tag", "sig", 13 + 8},  // SND_SEQ, whose trailing bytes are the tag
	} {
		t.Run(tc.name, func(t *testing.T) {
			s, err := newSealer(types.EncryptionKey{KeyType: 23, KeyValue: key})
			if err != nil {
				t.Fatal(err)
			}
			sig, data := vec(t, vecRC4Sig), vec(t, vecRC4Data)
			if tc.what == "sig" {
				sig[tc.at] ^= 0x01
			} else {
				data[tc.at] ^= 0x01
			}
			if _, err := s.unwrap(sig, data, plainLen); err == nil {
				t.Fatalf("tampered %s accepted", tc.name)
			}
		})
	}
}

// TestRC4WrapAgainstDerivedKeyVectors pins the *send* direction, which no
// frozen token can cover: wrapRC4 takes its confounder from crypto/rand, so its
// output is different every call.
//
// The way in is that Kcrypt and Ksign depend only on the session key and the
// sequence number. So the test lets the production code seal whatever it likes,
// then decrypts the result with impacket's Kcrypt and re-derives the checksum
// with impacket's Ksign. If wrapRC4 derived either key differently -- a dropped
// xorF0, the HMACs nested the other way round, the wrong endianness on the
// sequence number -- the recovered plaintext is garbage or the checksum
// disagrees. This needs no test seam in the production code, which is why it is
// shaped this way rather than by injecting a fixed confounder.
func TestRC4WrapAgainstDerivedKeyVectors(t *testing.T) {
	key := vec(t, vecRC4Key)
	plain := vec(t, vecPlaintext)
	kcrypt := vec(t, vecRC4Kcrypt)
	ksign := vec(t, vecRC4Ksign)

	s, err := newSealer(types.EncryptionKey{KeyType: 23, KeyValue: key})
	if err != nil {
		t.Fatal(err)
	}
	// Seal as the initiator at the vector's sequence number. Production only
	// ever seals as the initiator; wrapAs is what makes the sequence explicit.
	sig, data, err := s.wrapAs(plain, vecSeq, false)
	if err != nil {
		t.Fatal(err)
	}

	i := bytes.Index(sig, rc4OID)
	if i < 0 {
		t.Fatal("no GSS OID in signature")
	}
	token := sig[i+len(rc4OID) : i+len(rc4OID)+32]
	first8, sgn, confEnc := token[0:8], token[16:24], token[24:32]

	// TOK_ID 0201 | SGN_ALG 1100 (HMAC) | SEAL_ALG 1000 (RC4) | Filler ffff,
	// as impacket's WRAP structure lays it out. Asserted explicitly because
	// the checksum below reads first8 back out of the token we just produced,
	// so a wrong algorithm identifier would agree with itself and slip past
	// both this test and a round-trip -- while a real acceptor rejected it.
	if want := vec(t, "020111001000ffff"); !bytes.Equal(first8, want) {
		t.Fatalf("token header %x, want %x", first8, want)
	}

	// One RC4 stream under impacket's Kcrypt covers the confounder and then
	// the payload, in that order -- so decrypting them as one run recovers
	// both. Note this uses the frozen key, never a derivation of our own.
	c, err := rc4.NewCipher(kcrypt)
	if err != nil {
		t.Fatal(err)
	}
	conf := make([]byte, 8)
	c.XORKeyStream(conf, confEnc)
	gotPlain := make([]byte, len(data))
	c.XORKeyStream(gotPlain, data)
	if !bytes.Equal(gotPlain, plain) {
		t.Fatalf("payload did not decrypt under impacket's Kcrypt:\n got %x\nwant %x", gotPlain, plain)
	}

	// RFC 4757 §7.3, recomputed with stdlib primitives and the frozen Ksign so
	// nothing here shares code with the production derivation.
	seqLE := make([]byte, 4)
	binary.LittleEndian.PutUint32(seqLE, 13)
	m := md5.New()
	m.Write(seqLE)
	m.Write(first8)
	m.Write(conf)
	m.Write(plain)
	h := hmac.New(md5.New, ksign)
	h.Write(m.Sum(nil))
	if want := h.Sum(nil)[:8]; !bytes.Equal(sgn, want) {
		t.Fatalf("SGN_CKSUM mismatch:\n got %x\nwant %x", sgn, want)
	}
}

// TestAESUnwrapAcceptorVector proves the AES receive path reads a token built
// to RFC 4121 §4.2.4 by something other than us.
//
// The payload crypto here is go-krb5's and is vector-tested upstream, so what
// this actually pins is krbseal's own contribution: that it decrypts with
// GSSAPI_ACCEPTOR_SEAL rather than the initiator usage, un-rotates *left* by
// RRC, reads RRC from bytes 6:8, and accepts the echoed-header comparison
// against a header it did not write. Getting the key usage or the rotation
// direction backwards is exactly the kind of mistake a self-round-trip cannot
// see, because it would be applied identically at both ends.
func TestAESUnwrapAcceptorVector(t *testing.T) {
	key := vec(t, vecAESKey)
	plain := vec(t, vecPlaintext)

	s, err := newSealer(types.EncryptionKey{KeyType: 18, KeyValue: key})
	if err != nil {
		t.Fatal(err)
	}
	got, err := s.unwrap(vec(t, vecAESSig), vec(t, vecAESData), len(plain))
	if err != nil {
		t.Fatalf("unwrap of the AES vector failed: %v", err)
	}
	if !bytes.Equal(got, plain) {
		t.Fatalf("plaintext mismatch:\n got %q\nwant %q", got, plain)
	}
}
